//! Writing Rust source text.
//!
//! The generated files must already be in the layout `rustfmt` gives them
//! (the repository's `rustfmt.toml`: 120 columns, small heuristics at
//! their maximum), so that formatting the crate never changes them and a
//! byte comparison with a fresh run of the generator stays meaningful.
//! The arrays follow rustfmt's rules for array literals: one line when the
//! whole statement fits, otherwise several items per line when every item
//! is a literal at most 10 columns wide, otherwise one item per line.

use std::fmt::Write;

const MAX_WIDTH: usize = 120;
const SHORT_ITEM_WIDTH: usize = 10;
const INDENT: &str = "    ";

/// A generated Rust source file being written.
pub struct RustFile {
    text: String,
}

impl RustFile {
    /// Starts a file with the generated-file notice. `sources` names the
    /// UCD files the contents come from and `about` says what the file holds.
    pub fn new(about: &str, sources: &[&str], version: (u8, u8, u8)) -> RustFile {
        let (major, minor, update) = version;
        let notice = format!(
            "Generated by turbo-unicode-gen from {} of Unicode {major}.{minor}.{update}. Do not edit this file by \
             hand: change the generator and run it again as analysis/unicode/ucd/README.md describes.",
            join_names(sources)
        );
        let mut file = RustFile { text: String::new() };
        file.comment(&notice);
        file.line("//");
        file.comment(about);
        file
    }

    /// Appends one line.
    pub fn line(&mut self, line: &str) {
        self.text.push_str(line);
        self.text.push('\n');
    }

    /// Appends an empty line.
    pub fn blank(&mut self) {
        self.text.push('\n');
    }

    /// Appends `text` as `//` comment lines wrapped at 80 columns.
    pub fn comment(&mut self, text: &str) {
        for line in wrap(text, 80 - 3) {
            self.line(&format!("// {line}"));
        }
    }

    /// Appends `text` as `///` documentation lines wrapped at 80 columns.
    pub fn doc(&mut self, text: &str) {
        for line in wrap(text, 80 - 4) {
            self.line(&format!("/// {line}"));
        }
    }

    /// Appends `pub(crate) const NAME: TY = VALUE;` with its documentation.
    pub fn constant(&mut self, doc: &str, name: &str, ty: &str, value: &str) {
        self.doc(doc);
        self.line(&format!("pub(crate) const {name}: {ty} = {value};"));
    }

    /// Appends `pub(crate) static NAME: [TY; N] = [...];` with its
    /// documentation, laid out as rustfmt lays out an array literal.
    pub fn array(&mut self, doc: &str, name: &str, ty: &str, items: &[String]) {
        self.doc(doc);
        let head = format!("pub(crate) static {name}: [{ty}; {}] = [", items.len());
        let one_line = format!("{head}{}];", items.join(", "));
        if one_line.len() <= MAX_WIDTH {
            self.line(&one_line);
            return;
        }
        self.line(&head);
        if items.iter().all(|item| item.len() <= SHORT_ITEM_WIDTH) {
            self.mixed_items(items);
        } else {
            for item in items {
                self.line(&format!("{INDENT}{item},"));
            }
        }
        self.line("];");
    }

    /// The finished source text.
    pub fn finish(self) -> String {
        self.text
    }

    fn mixed_items(&mut self, items: &[String]) {
        let mut line = String::from(INDENT);
        for item in items {
            let added = if line.len() == INDENT.len() { item.len() + 1 } else { item.len() + 2 };
            if line.len() > INDENT.len() && line.len() + added >= MAX_WIDTH {
                self.line(&line);
                line.truncate(INDENT.len());
            }
            if line.len() > INDENT.len() {
                line.push(' ');
            }
            line.push_str(item);
            line.push(',');
        }
        if line.len() > INDENT.len() {
            self.line(&line);
        }
    }
}

/// `a`, `a and b`, `a, b and c`.
fn join_names(names: &[&str]) -> String {
    match names {
        [] => String::new(),
        [one] => (*one).to_owned(),
        [rest @ .., last] => format!("{} and {last}", rest.join(", ")),
    }
}

/// Splits `text` into lines of at most `width` columns at spaces.
fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut lines = Vec::new();
    let mut line = String::new();
    for word in text.split_ascii_whitespace() {
        if !line.is_empty() && line.len() + 1 + word.len() > width {
            lines.push(std::mem::take(&mut line));
        }
        if !line.is_empty() {
            line.push(' ');
        }
        line.push_str(word);
    }
    if !line.is_empty() {
        lines.push(line);
    }
    lines
}

/// A number in decimal.
pub fn dec(value: impl std::fmt::Display) -> String {
    value.to_string()
}

/// A code point as a hexadecimal literal, `0x1F600`.
pub fn hex(cp: u32) -> String {
    format!("0x{cp:X}")
}

/// A `char` literal; printable ASCII is written as itself, everything else
/// as a `\u{...}` escape.
pub fn char_lit(c: char) -> String {
    match c {
        '\'' => "'\\''".to_owned(),
        '\\' => "'\\\\'".to_owned(),
        ' '..='~' => format!("'{c}'"),
        _ => format!("'\\u{{{:X}}}'", c as u32),
    }
}

/// A string literal; printable ASCII is written as itself, everything
/// else as `\u{...}` escapes, so the generated files are plain ASCII.
pub fn str_lit(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            ' '..='~' => out.push(c),
            _ => {
                let _ = write!(out, "\\u{{{:X}}}", c as u32);
            }
        }
    }
    out.push('"');
    out
}

#[cfg(test)]
mod tests {
    use super::{RustFile, char_lit, str_lit};

    fn array(items: &[String]) -> String {
        let mut file = RustFile { text: String::new() };
        file.array("Doc.", "X", "u32", items);
        file.finish()
    }

    #[test]
    fn short_arrays_fit_on_one_line() {
        assert_eq!(array(&["1".into(), "2".into()]), "/// Doc.\npub(crate) static X: [u32; 2] = [1, 2];\n");
    }

    #[test]
    fn short_items_fill_lines_and_long_items_take_one_line_each() {
        let short: Vec<String> = (0..100).map(|i| format!("{}", 1000 + i)).collect();
        let text = array(&short);
        assert!(text.lines().all(|line| line.len() < 120));
        assert!(text.lines().nth(2).unwrap().matches(',').count() > 1);
        let long: Vec<String> = (0..30).map(|i| format!("\"a long string {i}\"")).collect();
        let text = array(&long);
        assert_eq!(text.lines().count(), 30 + 3);
    }

    #[test]
    fn literals_escape_everything_but_printable_ascii() {
        assert_eq!(str_lit("a\"\\\u{301}\u{1F600}"), "\"a\\\"\\\\\\u{301}\\u{1F600}\"");
        assert_eq!(char_lit('\''), "'\\''");
        assert_eq!(char_lit('x'), "'x'");
        assert_eq!(char_lit('\u{E9}'), "'\\u{E9}'");
    }
}
